package cn.dreamingfish.launcher.vanilla;
import cn.dreamingfish.launcher.downloads.TaskRequest;
import cn.dreamingfish.launcher.storage.LauncherJson;
import com.fasterxml.jackson.databind.JsonNode;
import java.io.*;
import java.time.*;
import java.util.*;
public record InstallationReceipt(String instanceId,String installationId,String versionId,String metadataSha1,Instant installedAt,Platform platform,Integer requiredJavaMajor,List<FileEntry> files,String fabricVersion,cn.dreamingfish.launcher.loaders.LoaderIdentity component) {
 public InstallationReceipt(String instanceId,String installationId,String versionId,String metadataSha1,Instant installedAt,Platform platform,Integer requiredJavaMajor,List<FileEntry> files,String fabricVersion){this(instanceId,installationId,versionId,metadataSha1,installedAt,platform,requiredJavaMajor,files,fabricVersion,null);}
 public cn.dreamingfish.launcher.GameInstance.LoaderKind loaderKind(){return component!=null?component.kind():fabricVersion!=null?cn.dreamingfish.launcher.GameInstance.LoaderKind.FABRIC:cn.dreamingfish.launcher.GameInstance.LoaderKind.VANILLA;}
 public String loaderVersion(){return component!=null?component.version():fabricVersion;}
 public InstallationReceipt(String instanceId,String installationId,String versionId,String metadataSha1,Instant installedAt,Platform platform,Integer requiredJavaMajor,List<FileEntry> files){this(instanceId,installationId,versionId,metadataSha1,installedAt,platform,requiredJavaMajor,files,null);}
 public static final int MAX_BYTES=32*1024*1024;
 public record FileEntry(String path,long size,String sha256){public FileEntry{var parsed=SafeInstallPath.parse(path);if(!Set.of("versions","libraries","assets","resources","logging").contains(parsed.getName(0).toString())||size<0||size>2L*1024*1024*1024||sha256==null||!sha256.matches("[0-9a-f]{64}"))throw new IllegalArgumentException("安装文件记录无效");}}
 public InstallationReceipt {TaskRequest.uuid(instanceId);TaskRequest.uuid(installationId);if(versionId==null||versionId.isBlank()||versionId.length()>128||metadataSha1==null||!metadataSha1.matches("[0-9a-f]{40}")||installedAt==null||platform==null||requiredJavaMajor!=null&&(requiredJavaMajor<1||requiredJavaMajor>100))throw new IllegalArgumentException("安装收据无效");files=List.copyOf(files);if(files.isEmpty()||files.size()>100000)throw new IllegalArgumentException("安装文件数量无效");SafeInstallPath.checkDistinct(files.stream().map(f->SafeInstallPath.parse(f.path())).toList());var profiles=files.stream().map(FileEntry::path).filter(p->Set.of("versions/fabric.json","versions/quilt.json","versions/loader.json").contains(p)).toList();String expected=component!=null?component.profilePath():fabricVersion!=null?"versions/fabric.json":null;if(component!=null&&fabricVersion!=null||expected==null&&!profiles.isEmpty()||expected!=null&&(!profiles.equals(List.of(expected)))||fabricVersion!=null&&!fabricVersion.matches("[A-Za-z0-9][A-Za-z0-9_.+\\-]{0,127}"))throw new IllegalArgumentException("加载器安装身份和profile不匹配");}
 public byte[] bytes()throws IOException{
  var map=new LinkedHashMap<String,Object>();map.put("schemaVersion",component!=null?3:fabricVersion==null?1:2);if(component!=null)map.put("loader",component);if(fabricVersion!=null)map.put("fabricVersion",fabricVersion);map.put("instanceId",instanceId);map.put("installationId",installationId);map.put("versionId",versionId);map.put("metadataSha1",metadataSha1);map.put("installedAt",installedAt.toString());map.put("platform",Map.of("osName",platform.osName(),"osVersion",platform.osVersion(),"arch",platform.arch(),"bits",platform.bits()));map.put("requiredJavaMajor",requiredJavaMajor);map.put("files",files);byte[] bytes=LauncherJson.write(map);if(bytes.length>MAX_BYTES)throw new cn.dreamingfish.launcher.downloads.TaskFailure("RECORD_TOO_LARGE","安装文件记录超过 32 MiB 上限，未发布安装");return bytes;
 }
 private static cn.dreamingfish.launcher.loaders.LoaderIdentity loaderIdentity(JsonNode n){keys(n,Set.of("kind","version"));return new cn.dreamingfish.launcher.loaders.LoaderIdentity(cn.dreamingfish.launcher.GameInstance.LoaderKind.valueOf(LauncherJson.text(n,"kind",16)),LauncherJson.text(n,"version",128));}
 static void keys(JsonNode n,Set<String> expected){var actual=new HashSet<String>();n.fieldNames().forEachRemaining(actual::add);if(!n.isObject()||!actual.equals(expected))throw new IllegalArgumentException("收据字段不匹配");}
 public static InstallationReceipt parse(byte[] bytes)throws IOException{
  try{var n=LauncherJson.read(bytes,MAX_BYTES);boolean fabric=n.path("schemaVersion").isInt()&&n.path("schemaVersion").intValue()==2;var fields=new HashSet<>(Set.of("schemaVersion","instanceId","installationId","versionId","metadataSha1","installedAt","platform","requiredJavaMajor","files"));boolean loader=n.path("schemaVersion").isInt()&&n.path("schemaVersion").intValue()==3;if(loader)fields.add("loader");if(fabric)fields.add("fabricVersion");keys(n,fields);if(!n.path("schemaVersion").isInt()||!Set.of(1,2,3).contains(n.path("schemaVersion").intValue())||!n.path("files").isArray()||n.path("files").size()>100000)throw new IllegalArgumentException("收据格式无效");var p=n.path("platform");keys(p,Set.of("osName","osVersion","arch","bits"));if(!p.path("bits").isInt())throw new IllegalArgumentException("平台位数无效");var platform=new Platform(LauncherJson.text(p,"osName",16),LauncherJson.text(p,"osVersion",256),LauncherJson.text(p,"arch",64),p.path("bits").intValue());
   var files=new ArrayList<FileEntry>();for(var f:n.path("files")){keys(f,Set.of("path","size","sha256"));if(!f.path("size").isIntegralNumber()||!f.path("size").canConvertToLong())throw new IllegalArgumentException("安装长度无效");files.add(new FileEntry(LauncherJson.text(f,"path",1024),f.path("size").longValue(),LauncherJson.text(f,"sha256",64)));}
   var major=n.path("requiredJavaMajor");if(!major.isNull()&&!major.isInt())throw new IllegalArgumentException("Java 要求无效");return new InstallationReceipt(LauncherJson.text(n,"instanceId",36),LauncherJson.text(n,"installationId",36),LauncherJson.text(n,"versionId",128),LauncherJson.text(n,"metadataSha1",40),Instant.parse(LauncherJson.text(n,"installedAt",64)),platform,major.isNull()?null:major.intValue(),files,fabric?LauncherJson.text(n,"fabricVersion",128):null,loader?loaderIdentity(n.path("loader")):null);
  }catch(RuntimeException error){throw new IOException("安装收据损坏",error);}
 }
}
